import{_ as l,a0 as r,w as o,s as a,ao as s,I as p,a1 as T,A as e,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Linux 黑話解釋：TTY 是什麼？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux 黑話解釋：TTY 是什麼？ | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 黑話解釋：TTY 是什麼？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 黑話解釋：TTY 是什麼？ | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20211212 What is TTY in Linux","title":"Linux 黑話解釋：TTY 是什麼？","tag":"202112","desc":""},"relativePath":"202112/20211212 What is TTY in Linux.md","filePath":"[post].md"}'),u={name:"202112/20211212 What is TTY in Linux.md"};function d(m,t,x,Y,f,L){const n=r("Link");return o(),a("div",null,[t[28]||(t[28]=s('<h1 id="linux-黑話解釋-tty-是什麼" tabindex="-1">Linux 黑話解釋：TTY 是什麼？ <a class="header-anchor" href="#linux-黑話解釋-tty-是什麼" aria-label="Permalink to “Linux 黑話解釋：TTY 是什麼？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202112/18/155143cz6aplfi8i6elmll.jpg" alt=""></p><p>談到 Linux 和 UNIX 時，你一定聽説過 “TTY” 這個術語，但是，這玩意是什麼？</p><p>作為一個桌面用户，它對你有用嗎？你需要它嗎？你能用它做什麼？</p><p>在本文中，讓我向你介紹這些，幫助你熟悉 Linux 中的 TTY。</p><p>注意：這個問題沒有明確的答案，但它與過去的輸入/輸出設備的交互方式有關。因此，你必須瞭解一些歷史，才能清楚地瞭解情況。</p><h3 id="tty-背後的歷史" tabindex="-1">“TTY” 背後的歷史 <a class="header-anchor" href="#tty-背後的歷史" aria-label="Permalink to ““TTY” 背後的歷史”">​</a></h3><p>一切始於 19 世紀 30 年代的<ruby>電傳打印機<rt>Teleprinter</rt></ruby>。</p><p>電傳打印機可以讓你通過電線發送或接受消息，它取代了摩爾斯電碼通信，那是一種需要兩個操作員才能有效地相互通信的方式。</p><p>一台電傳打印機只需要一個操作員就可以輕鬆地傳遞消息。雖然它沒有現代佈局的鍵盤，但它的系統後來由 Donald Murray 在 1901 年進行了改良，包括了一個類似打字機的鍵盤。</p><p>Murray 電碼減少了操作員發送消息的工作量。這才使得電傳打印機在 1908 年有了發展成為商業<ruby>電傳打字機<rt>Teletypewriter</rt></ruby>的可能。TTY 即是電傳打字機的縮寫。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/WACsOperateTeletype.jpg?resize=429%2C371&amp;ssl=1" alt="二戰期間在倫敦實際使用的電傳打字機 | 圖片來源於維基百科"></p><p>電傳打字機和普通<ruby>打字機<rt>typewriter</rt></ruby>的區別在於，電傳打字機連接到通信設備，直接發送輸入的消息。</p>',13)),p("p",null,[T(n,{href:"https://en.wikipedia.org/wiki/Teletype_Corporation#/media/File:What-is-teletype.jpg"},{default:e(()=>[...t[0]||(t[0]=[i("電傳打字機使人類在沒有計算機的情況下通過電線進行更快的通信成為可能",-1)])]),_:1}),t[1]||(t[1]=i("。",-1))]),t[29]||(t[29]=s('<p>從這時起，“TTY” 一詞就存在了。</p><h3 id="相對-現代的概念" tabindex="-1">（相對）現代的概念 <a class="header-anchor" href="#相對-現代的概念" aria-label="Permalink to “（相對）現代的概念”">​</a></h3><p>現在，你一定想知道，它是如何進入現代計算機和 Linux 的？</p><p>最初是當電傳打字機進入了市場，幾年後半導體晶體管發展起來，然後演變成微處理器，為計算機的出現做好了準備。</p><p>最初的計算機沒有鍵盤的概念，<ruby>打孔卡<rt>Punch card</rt></ruby>就是輸入的方法。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/punch-card-program.jpg?resize=600%2C274&amp;ssl=1" alt="一種插入計算機而不是通過鍵盤（TTY）輸入的打孔卡計算機程序 | 圖片來源於維基百科"></p><p>隨着計算機的發展，批量輸入的打孔卡最終被電傳打字機取代，成為一種方便的輸入/輸出設備。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/LGP-30-early-computer-1956.jpg?resize=800%2C600&amp;ssl=1" alt="1956 年的 LGP-30 計算機，附帶 TTY"></p><p>隨着技術的進步，電傳打字機被電子技術“虛擬化”了。因此，你不需要一個物理的、機械的 TTY，而是一個虛擬的電子 TTY。</p><p>早期的計算機甚至沒有視頻屏幕。字符被打印在紙上而不是顯示在屏幕上。因此，你會看到“<ruby>打印<rt>print</rt></ruby>”這個術語而不是“<ruby>顯示<rt>display</rt></ruby>”。隨着技術的進步，視頻顯示後來被添加到終端中。</p><p>換句話説，你可能聽説過把它們稱為“視頻終端”。或者，你可以稱它們為“物理”終端。</p><p>後來，它們演變成具有更強的能力和功能的軟件仿真的終端。</p>',12)),p("p",null,[t[3]||(t[3]=i("這就是所謂的“",-1)),t[4]||(t[4]=p("ruby",null,[i("終端仿真器"),p("rt",null,"terminal emulator")],-1)),t[5]||(t[5]=i("”，如 GNOME 終端或 Konsole，或者其他 ",-1)),T(n,{href:"https://itsfoss.com/linux-terminal-emulators/"},{default:e(()=>[...t[2]||(t[2]=[i("你在 Linux 上找到的各種終端仿真器",-1)])]),_:1}),t[6]||(t[6]=i("。",-1))]),t[30]||(t[30]=p("h3",{id:"所以-linux-中的-tty-到底是什麼",tabindex:"-1"},[i("所以，Linux 中的 TTY 到底是什麼？ "),p("a",{class:"header-anchor",href:"#所以-linux-中的-tty-到底是什麼","aria-label":"Permalink to “所以，Linux 中的 TTY 到底是什麼？”"},"​")],-1)),p("p",null,[t[8]||(t[8]=i("在 Linux 或 UNIX 中，TTY 變為了一個抽象設備。有時它指的是一個物理輸入設備，例如串口，有時它指的是一個允許用户和系統交互的虛擬 TTY（",-1)),T(n,{href:"https://unix.stackexchange.com/questions/4126/what-is-the-exact-difference-between-a-terminal-a-shell-a-tty-and-a-con"},{default:e(()=>[...t[7]||(t[7]=[i("參考此處",-1)])]),_:1}),t[9]||(t[9]=i("）。",-1))]),t[31]||(t[31]=p("p",null,"TTY 是 Linux 或 UNIX 的一個子系統，它通過 TTY 驅動程序在內核級別實現進程管理、行編輯和會話管理。",-1)),t[32]||(t[32]=p("p",null,"在編程的場景下，你還需要深入研究。但是考慮到本文的範圍，這可能是一個容易理解的定義。",-1)),p("p",null,[t[11]||(t[11]=i("如果你好奇的話，你可以查看一個有點舊的資源（",-1)),T(n,{href:"https://www.linusakesson.net/programming/tty/index.php"},{default:e(()=>[...t[10]||(t[10]=[i("TTY 揭秘",-1)])]),_:1}),t[12]||(t[12]=i("），它儘可能的澄清了 Linux 和 UNIX 系統中的 TTY 的各種技術細節。",-1))]),t[33]||(t[33]=s('<p>事實上，每當你在系統中啓動一個終端仿真器或使用任何類型的 shell 時，它都會與虛擬 TTY（也被稱為<ruby>偽 TTY<rt>pseudo-TTY</rt></ruby>，即 PTY）進行交互。</p><p>你可以在終端仿真器中輸入 <code>tty</code> 來找到相關聯的 PTY。</p><h3 id="如何在-linux-中訪問-tty" tabindex="-1">如何在 Linux 中訪問 TTY？ <a class="header-anchor" href="#如何在-linux-中訪問-tty" aria-label="Permalink to “如何在 Linux 中訪問 TTY？”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/ubuntu-tty.png?resize=800%2C449&amp;ssl=1" alt=""></p><p>在 Linux 中很容易訪問 TTY。事實上，當我不知道它是什麼時，我不小心打開了它，於是對要做什麼、如何擺脱它感到恐慌。</p><p>在大多數 <em>發行版</em> 中，你可以使用以下鍵盤快捷鍵來得到 TTY 屏幕：</p><ul><li><code>CTRL + ALT + F1</code> – 鎖屏</li><li><code>CTRL + ALT + F2</code> – 桌面環境</li><li><code>CTRL + ALT + F3</code> – TTY3</li><li><code>CTRL + ALT + F4</code> – TTY4</li><li><code>CTRL + ALT + F5</code> – TTY5</li><li><code>CTRL + ALT + F6</code> – TTY6</li></ul><p>你最多可以訪問六個 TTY。但是，前兩個快捷方式指向發行版的鎖定屏幕和桌面環境。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/ubuntu-tty4.png?resize=420%2C124&amp;ssl=1" alt=""></p><p>而其他快捷方式將會讓你進入一個命令列界面。</p><h3 id="什麼時候應該使用-tty" tabindex="-1">什麼時候應該使用 TTY？ <a class="header-anchor" href="#什麼時候應該使用-tty" aria-label="Permalink to “什麼時候應該使用 TTY？”">​</a></h3><p>TTY 不僅是一個技術寶藏，即使像我這樣不是開發人員的用户，它也很有用。</p><p>在圖形桌面環境凍結的情況下，它應該可以派上用場。在某些情況下，從 TTY 重建桌面環境能幫助解決程序問題。</p><p>或者，你也可以選擇在 TTY 中執行任務，例如更新 Linux 系統等。在這些情況下，你不希望顯示問題中斷你的進程。</p><p>最壞的情況是，如果圖形用户界面失去響應，你可以進入 TTY 並重新啓動計算機。</p><p>有些用户還喜歡在 TTY 的幫助下傳輸大文件（我不是其中之一）。</p><h3 id="linux-中的-tty-命令" tabindex="-1">Linux 中的 TTY 命令 <a class="header-anchor" href="#linux-中的-tty-命令" aria-label="Permalink to “Linux 中的 TTY 命令”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/ubuntu-terminal-tty-command.png?resize=800%2C544&amp;ssl=1" alt=""></p><p>當你在終端模擬器中輸入 <code>tty</code> 時，它將打印連接到標準輸入的終端文件名，就像手冊頁描述的一樣。</p><p>換句話説，要知道你連接的 TTY 編號，只需輸入 <code>tty</code>。並且，如果有多個用户遠程連接到 Linux 機器，你可以使用 <code>who</code> 命令來檢查其他用户連接到的是哪個 TTY。</p><hr>',21)),p("p",null,[t[14]||(t[14]=i("via: ",-1)),T(n,{href:"https://itsfoss.com/what-is-tty-in-linux/"},{default:e(()=>[...t[13]||(t[13]=[i("https://itsfoss.com/what-is-tty-in-linux/",-1)])]),_:1})]),p("p",null,[t[19]||(t[19]=i("作者：",-1)),T(n,{href:"https://itsfoss.com/author/ankush/"},{default:e(()=>[...t[15]||(t[15]=[i("Ankush Das",-1)])]),_:1}),t[20]||(t[20]=i(" 選題：",-1)),T(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[16]||(t[16]=[i("lujun9972",-1)])]),_:1}),t[21]||(t[21]=i(" 譯者：",-1)),T(n,{href:"https://github.com/MjSeven"},{default:e(()=>[...t[17]||(t[17]=[i("MjSeven",-1)])]),_:1}),t[22]||(t[22]=i(" 校對：",-1)),T(n,{href:"https://github.com/wxy"},{default:e(()=>[...t[18]||(t[18]=[i("wxy",-1)])]),_:1})]),p("p",null,[t[25]||(t[25]=i("本文由 ",-1)),T(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[23]||(t[23]=[i("LCTT",-1)])]),_:1}),t[26]||(t[26]=i(" 原創編譯，",-1)),T(n,{href:"https://linux.cn/"},{default:e(()=>[...t[24]||(t[24]=[i("Linux中國",-1)])]),_:1}),t[27]||(t[27]=i(" 榮譽推出",-1))])])}const g=l(u,[["render",d]]);export{C as __pageData,g as default};
